import { test, expect } from '@playwright/test';

async function __vis(loc) { try { return await loc.isVisible(); } catch { return false; } }
async function __txt(loc) { try { return (await loc.textContent()) || ''; } catch { return ''; } }

async function gotoStory(page, route, primary) {
  const resp = await page.goto(route);
  const nf = await __vis(page.locator('[data-testid*="not-found" i], [data-testid*="notfound" i]').first());
  if (nf && primary && primary !== route) { return await page.goto(primary); }
  return resp;
}

