    const __resp = await gotoStory(page, '/parent/login', '/parent/login');
    await page.waitForLoadState('networkidle', { timeout: 5_000 }).catch(() => {});
    expect(__apiErrs, 'a server-side /api error fired during this story (5xx — root cause, not a UI mismatch): ' + JSON.stringify(__apiErrs)).toEqual([]);
